int findMaxSubsequenceLength(int[] A, int N, int D) {
    int maxLength = 0;
    int currentLength = 1;

    for (int i = 1; i < N; i++) {
        if (Math.abs(A[i] - A[i - 1]) <= D) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
        }
    }
    maxLength = Math.max(maxLength, currentLength);

    return maxLength;
}
